function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Bitset' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with Bitset(size).';
  const size = args[0][0];
  if (!Number.isInteger(size) || size < 1 || size > 100000) return 'size is a whole number from 1 to 10^5.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls after the constructor.';
  let strings = 0;
  let asked = false;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (op === 'fix' || op === 'unfix') {
      if (a.length !== 1 || !Number.isInteger(a[0]) || a[0] < 0 || a[0] >= size) return `${op} needs an idx from 0 to size - 1.`;
    } else if (['flip', 'all', 'one', 'count', 'toString'].includes(op)) {
      if (a.length !== 0) return `${op} takes no arguments.`;
      if (op !== 'flip') asked = true;
      if (op === 'toString') strings++;
    } else {
      return 'Only fix, unfix, flip, all, one, count and toString can follow the constructor.';
    }
  }
  if (strings > 5) return 'At most 5 calls to toString.';
  if (!asked) return 'Make at least one call to all, one, count or toString.';
  return null;
}

