class Bitset {
  constructor(size) {
    this.size = size;
    this.bits = new Array(size).fill(0);
    this.flipped = 0;
    this.ones = 0;
  }

  fix(idx) {
    if ((this.bits[idx] ^ this.flipped) === 0) {
      this.bits[idx] ^= 1;
      this.ones++;
    }
  }

  unfix(idx) {
    if ((this.bits[idx] ^ this.flipped) === 1) {
      this.bits[idx] ^= 1;
      this.ones--;
    }
  }

  flip() {
    this.flipped ^= 1;
    this.ones = this.size - this.ones;
  }

  all() {
    return this.ones === this.size;
  }

  one() {
    return this.ones > 0;
  }

  count() {
    return this.ones;
  }

  toString() {
    return this.bits.map(bit => bit ^ this.flipped).join('');
  }
}

