function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const bitCount = large ? (rand() < 0.7 ? int(5000, 10000) : int(1, 40)) : int(1, 6);
  const calls = large ? 499 : int(1, 15);
  const operations = ['Bitset'];
  const args = [[bitCount]];
  const queries = ['all', 'one', 'count'];
  let strings = 0;
  let asked = false;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (i === calls - 1 && !asked) {
      operations.push(queries[int(0, 2)]);
      args.push([]);
    } else if (roll < 0.35) {
      operations.push('fix');
      args.push([int(0, bitCount - 1)]);
    } else if (roll < 0.6) {
      operations.push('unfix');
      args.push([int(0, bitCount - 1)]);
    } else if (roll < 0.72) {
      operations.push('flip');
      args.push([]);
    } else if (roll < 0.76 && strings < 5) {
      operations.push('toString');
      args.push([]);
      strings++;
      asked = true;
    } else {
      operations.push(queries[int(0, 2)]);
      args.push([]);
      asked = true;
    }
  }
  return [operations, args];
}
